/**
 * Browser-only loader. Statically imports pkg-web (wasm-pack --target=web)
 * so vite library builds bundle ONLY the web target — the nodejs target
 * (pkg/, with `require('fs')`) never makes it into a browser IIFE.
 *
 * Usage:
 *   import { initWasmEngineWeb } from 'tnaj-wasm-engine/web';
 *   await initWasmEngineWeb();
 *   // then any shim function (centralitiesWasm, bootstrapTnaWasm, …) works.
 */
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore — generated by wasm-pack, no .d.ts at lib-build time
import __wbg_init, * as webMod from '../wasm/pkg-web/tnaj_wasm.js';
import { setExports, isInitialized } from './load-shared.js';
import type { WasmEngineExports } from './load.js';
export { isInitialized, getExports } from './load-shared.js';

/**
 * Initialize the WASM engine in a browser context.
 *
 * `wasmUrl` (optional): override where the .wasm bytes come from. By
 * default, wasm-pack's `__wbg_init` uses `new URL('tnaj_wasm_bg.wasm',
 * import.meta.url)` — so the bundler is expected to colocate the .wasm
 * alongside the JS. When inlining the IIFE into a single HTML, pass a
 * blob URL or a data URL pointing at the .wasm bytes.
 */
export async function initWasmEngineWeb(wasmUrl?: string | URL | Request | Response | BufferSource | WebAssembly.Module): Promise<void> {
  if (isInitialized()) return;
  // Cast so we don't have to thread the full wasm-bindgen init signature.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  await (__wbg_init as any)(wasmUrl);
  const mod = webMod as unknown as WasmEngineExports;
  setExports({
    bootstrap_inner_wasm: mod.bootstrap_inner_wasm,
    bootstrap_tna_wasm: mod.bootstrap_tna_wasm,
    permutation_test_wasm: mod.permutation_test_wasm,
    compare_weight_matrices_wasm: mod.compare_weight_matrices_wasm,
    markov_order_test_wasm: mod.markov_order_test_wasm,
    estimate_cs_wasm: mod.estimate_cs_wasm,
    rng_next_n: mod.rng_next_n,
    centralities_wasm: mod.centralities_wasm,
    passage_time_wasm: mod.passage_time_wasm,
    markov_stability_wasm: mod.markov_stability_wasm,
    honem_wasm: mod.honem_wasm,
    path_dependence_wasm: mod.path_dependence_wasm,
    mogen_wasm: mod.mogen_wasm,
    hypa_wasm: mod.hypa_wasm,
    hon_wasm: mod.hon_wasm,
    pathways_hon_wasm: mod.pathways_hon_wasm,
    pathways_hypa_wasm: mod.pathways_hypa_wasm,
    pathways_mogen_wasm: mod.pathways_mogen_wasm,
    casedrop_reliability_wasm: mod.casedrop_reliability_wasm,
    reliability_analysis_wasm: mod.reliability_analysis_wasm,
    cluster_string_wasm: mod.cluster_string_wasm,
    cluster_from_dist_wasm: mod.cluster_from_dist_wasm,
    cluster_numeric_wasm: mod.cluster_numeric_wasm,
    mmm_wasm: mod.mmm_wasm,
  });
}
