/**
 * Browser-only init for tnaw. Pulls in `tnaj-wasm-engine/web` so vite
 * library builds bundle only the wasm-pack web target (avoids the nodejs
 * CJS `require('fs')` path).
 */
import { initWasmEngine, isInitialized } from '../wasm-engine/index-web.js';

let _initPromise: Promise<void> | null = null;

export async function initTnaw(): Promise<void> {
  if (isInitialized()) return;
  if (_initPromise) return _initPromise;
  _initPromise = initWasmEngine();
  await _initPromise;
}

export function isTnawReady(): boolean {
  return isInitialized();
}

export function assertReady(): void {
  if (!isInitialized()) {
    throw new Error(
      'tnaw: WASM engine not initialized. Call `await initTnaw()` before using any tnaw function.',
    );
  }
}
